CREATE TABLE IF NOT EXISTS organizations(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS users(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),discord_id TEXT NOT NULL UNIQUE,username TEXT NOT NULL,global_name TEXT,avatar TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS organization_members(organization_id UUID NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,role TEXT NOT NULL CHECK(role IN('owner','administrator','site_manager','operator','viewer')),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(organization_id,user_id));
CREATE TABLE IF NOT EXISTS organization_invitations(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),organization_id UUID NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,discord_id TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('owner','administrator','site_manager','operator','viewer')),expires_at TIMESTAMPTZ,accepted_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(organization_id,discord_id));
CREATE TABLE IF NOT EXISTS sites(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),organization_id UUID NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,name TEXT NOT NULL,address JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS locations(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),site_id UUID NOT NULL REFERENCES sites(id) ON DELETE CASCADE,name TEXT NOT NULL,address JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS panels(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),location_id UUID NOT NULL REFERENCES locations(id) ON DELETE CASCADE,name TEXT NOT NULL,credential_hash TEXT NOT NULL UNIQUE,last_seen_at TIMESTAMPTZ,status TEXT NOT NULL DEFAULT 'unknown' CHECK(status IN('online','offline','unknown')),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS site_contacts(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),site_id UUID NOT NULL REFERENCES sites(id) ON DELETE CASCADE,name TEXT NOT NULL,phone TEXT,email TEXT,position INTEGER NOT NULL DEFAULT 0,enabled BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS location_contacts(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),location_id UUID NOT NULL REFERENCES locations(id) ON DELETE CASCADE,site_contact_id UUID REFERENCES site_contacts(id) ON DELETE CASCADE,mode TEXT NOT NULL CHECK(mode IN('add','override','exclude')),name TEXT,phone TEXT,email TEXT,position INTEGER NOT NULL DEFAULT 0,enabled BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS incidents(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),organization_id UUID NOT NULL REFERENCES organizations(id),site_id UUID NOT NULL REFERENCES sites(id),location_id UUID NOT NULL REFERENCES locations(id),panel_id UUID REFERENCES panels(id),event_type TEXT NOT NULL,payload JSONB NOT NULL DEFAULT '{}',status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','acknowledged','resolved')),occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),acknowledged_at TIMESTAMPTZ,resolved_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS incidents_org_status_idx ON incidents(organization_id,status,occurred_at DESC);
CREATE INDEX IF NOT EXISTS locations_site_idx ON locations(site_id);
CREATE INDEX IF NOT EXISTS panels_location_idx ON panels(location_id);
